#!/usr/bin/env python3
"""Package existing original masters and their authoring record, not new music."""
import hashlib,json,pathlib,platform,zipfile,subprocess
root=pathlib.Path(__file__).resolve().parents[2]
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
credits='''TIDEGLASS — ORIGINAL SOUNDTRACK\n\n01 A Harbor of Small Lights — D Dorian, 60 BPM\n02 The Glass Current — G suspended / major, 72 BPM\n03 Where the Sky Comes Home — F Lydian / D Dorian, 54 BPM\n\nOriginal musical material, voicing, melody, synthesis and arrangement authored\nfor Tideglass by its AI development team under the project owner's direction.\nNo third-party recordings, samples, reference tracks or copied melody were\nincorporated. The source score and synthesis adapter accompany these masters.\n\nThis is a record of original authoring, not an assertion of legal copyright\neligibility, exclusivity, or a legal rights opinion. The project owner's review\nof distribution terms remains a release gate. The package is prepared for the\nTideglass supporter offer; no paid entitlement or public download service is\nclaimed by this local file.\n\nProduction: 48 kHz, 24-bit stereo PCM WAV. Runtime: AAC LC, 128 kbit/s.\nNumerical level/loop measurements are available in render-measurements.json.\nHuman speaker/headphone audition and native interruption tests are pending.\n\nTools: original Python/Numpy synthesis; SciPy numerical measurements; SoundFile\nWAV encoding; macOS afconvert AAC encoding. These tools' code or libraries are\nnot embedded in the audio recordings. The source adapter requires the versions\nrecorded in requirements.lock.txt.\n'''
(root/'source/audio/CREDITS.txt').write_text(credits)
cover='''<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="1200" viewBox="0 0 1200 1200"><rect width="1200" height="1200" fill="#071923"/><circle cx="600" cy="500" r="310" fill="#102a37" stroke="#294753" stroke-width="2"/><path d="M160 730 Q380 620 600 730 T1040 730 M160 770 Q380 660 600 770 T1040 770" fill="none" stroke="#79e0cc" stroke-width="3"/><path d="M555 680 L570 380 L630 380 L645 680Z" fill="#a1bac3"/><rect x="559" y="346" width="82" height="44" fill="#f4ca88"/><path d="M548 346 L600 306 L652 346Z" fill="#79e0cc"/><path d="M600 367 L230 470 M600 367 L970 470" stroke="#f4ca88" opacity=".4" stroke-width="3"/><circle cx="770" cy="260" r="5" fill="#f4ca88"/><circle cx="830" cy="320" r="4" fill="#79e0cc"/><path d="M770 260 L830 320 L880 250" stroke="#79e0cc" fill="none"/><circle cx="880" cy="250" r="4" fill="#79e0cc"/><text x="600" y="900" text-anchor="middle" fill="#e6eee9" font-family="serif" font-size="92" letter-spacing="12">TIDEGLASS</text><text x="600" y="966" text-anchor="middle" fill="#a1bac3" font-family="sans-serif" font-size="24" letter-spacing="7">ORIGINAL SOUNDTRACK</text></svg>'''
(root/'source/audio/cover.svg').write_text(cover)
report=json.loads((root/'release/audio/render-measurements.json').read_text())
mastermembers=[m for m in report['members'] if m['bus']=='music']
download=root/'release/downloads/tideglass-original-soundtrack.zip';download.parent.mkdir(parents=True,exist_ok=True)
with zipfile.ZipFile(download,'w',zipfile.ZIP_DEFLATED,compresslevel=6) as z:
 for i,m in enumerate(mastermembers,1): z.write(root/m['source_path'],f'{i:02d}-{pathlib.Path(m["source_path"]).name}')
 for rel,name in [('source/audio/CREDITS.txt','CREDITS.txt'),('source/audio/cover.svg','cover.svg'),('source/audio/score/tideglass.score.json','source/tideglass.score.json'),('tools/audio/render_score.py','source/render_score.py'),('tools/audio/requirements.lock.txt','source/requirements.lock.txt'),('release/audio/render-measurements.json','render-measurements.json')]:z.write(root/rel,name)
package={'schema_version':1,'id':'audio.soundtrack','status':'authored_pending_independent_review','reuses_ambient_members':[m['id'] for m in mastermembers],'download_path':str(download.relative_to(root)),'download_sha256':sha(download),'download_bytes':download.stat().st_size,'initial_install':False,'delivery_status':'local_package_only_authenticated_host_and_entitlement_adapter_pending','approved_host_url':None,'purchase_restore_evidence':None,'rights_review_status':'original_authoring_record_present_owner_distribution_terms_review_pending'}
for base in ['source/audio','game/assets/audio']:
 p=root/base/'audio.soundtrack/package.json';p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(package,indent=2)+'\n')
cap={'schema_version':1,'capability_status':'authored_synthesis_and_actual_exports_demonstrated','original_authoring_evidence':['source/audio/score/tideglass.score.json','tools/audio/render_score.py','source/audio/masters/','release/audio/render-measurements.json'],'third_party_audio_incorporated':False,'legal_copyright_or_exclusivity_asserted':False,'distribution_rights_status':'original_authoring_record_no_incorporated_third_party_media_owner_terms_review_pending','standalone_download':package,'environment':{'os':platform.platform(),'python':platform.python_version(),'afconvert':subprocess.run(['/usr/bin/afconvert','-h'],capture_output=True,text=True).stderr.splitlines()[:3]},'native_adapter':'game/mobile/lib/audio_bus.dart','reviewer':None,'pending':['Human listening and mix approval','Actual native decode and interruption checks','Project owner distribution terms review','Authenticated download hosting and restored paid entitlement test']}
(root/'release/audio/capability-and-rights.json').write_text(json.dumps(cap,indent=2)+'\n')
contract_path=root/'implementation/art/production_contract.json';contract=json.loads(contract_path.read_text())
manifest_path=root/'implementation/content/launch_manifest.json';manifest=json.loads(manifest_path.read_text())
for row in contract['assets']:
 if row['category']!='audio':continue
 asset=row['asset_id']; src=root/row['source_descriptor_path'];out=root/row['export_descriptor_path']
 descriptor=json.loads(src.read_text());members=descriptor.get('members',[])
 sources=['source/audio/score/tideglass.score.json','tools/audio/render_score.py','source/audio/CREDITS.txt']+[m['source_path'] for m in members]
 exports=[row['export_descriptor_path']]+[m['runtime_path'] for m in members]
 if asset=='asset.audio.soundtrack':sources+=['source/audio/cover.svg'];exports+=[package['download_path']]
 provenance={'asset_id':asset,'author_or_tool':'Tideglass AI art/audio engineer; authored score and original mathematical synthesis','creation_date':'2026-10-16','source_media_paths':sources,'source_media_sha256':{p:sha(root/p) for p in sources},'source_kind':'original_authored_score_and_synthesis_no_samples','license_or_authorship_basis':'Documented original composition and synthesis; no incorporated third-party audio. This is not a claim of legal copyright or exclusivity. Owner distribution-terms review remains pending.','license_evidence_paths':['release/audio/capability-and-rights.json','source/audio/CREDITS.txt'],'allowed_uses':['Prepared for Tideglass in-game audio','Prepared same ambient masters for supporter soundtrack; public delivery terms pending owner review'],'attribution_text':'Original music and sound: Tideglass AI development team, project-owner direction.','reference_asset_permissions':'No external reference media used','export_tool_and_version':report['tool_versions'],'exported_paths':exports,'exported_sha256':{p:sha(root/p) for p in exports},'reviewer':None,'review_evidence':None}
 (root/row['provenance_path']).write_text(json.dumps(provenance,indent=2)+'\n')
 row.update(status='in_production',source_exists=True,export_exists=True,verification_evidence=None)
 for a in manifest['assets']:
  if a['id']==asset:a.update(delivery_status='in_production',source_path=row['source_descriptor_path'],license_evidence=row['provenance_path'])
for a in manifest['audio']:a['production_status']='in_production'
contract['audio_delivery'].update(capability_status='authored_synthesis_and_actual_exports_demonstrated',license_status='original_authoring_record_owner_distribution_terms_review_pending',actual_audio_created=True)
contract_path.write_text(json.dumps(contract,indent=2)+'\n');manifest_path.write_text(json.dumps(manifest,indent=2)+'\n')
print(json.dumps({'soundtrack_bytes':download.stat().st_size,'sha256':sha(download),'audio_packages_authored':5,'verified':0}))
